begin;
-- Reminders use original invoice dates; partial payments never move due_on.
create table public.provider_billing_due_tasks_v1(invoice_id uuid not null references public.provider_invoices(id),milestone text not null check(milestone in('J4','J6','J7','OVERDUE')),scheduled_on date not null,primary key(invoice_id,milestone));
alter table public.provider_billing_due_tasks_v1 enable row level security;
revoke all on public.provider_billing_due_tasks_v1 from public,anon,authenticated,service_role;
grant select on public.provider_billing_due_tasks_v1 to authenticated;
create policy billing_due_task_read on public.provider_billing_due_tasks_v1 for select to authenticated using(exists(select 1 from public.provider_invoices i where i.id=invoice_id and private.provider_billing_access(i.provider_organization_id,auth.uid())));
create trigger billing_due_task_immutable before update or delete on public.provider_billing_due_tasks_v1 for each row execute function private.prevent_update_delete();
create function private.provider_invoice_due_tasks_v1()returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$begin
 insert into public.provider_billing_due_tasks_v1(invoice_id,milestone,scheduled_on)values(new.id,'J4',greatest(new.issued_on,new.due_on-3)),(new.id,'J6',greatest(new.issued_on,new.due_on-1)),(new.id,'J7',new.due_on),(new.id,'OVERDUE',new.due_on+1);return new;end$$;
revoke all on function private.provider_invoice_due_tasks_v1()from public,anon,authenticated,service_role;
create trigger provider_invoice_due_tasks after insert on public.provider_invoices for each row execute function private.provider_invoice_due_tasks_v1();
insert into public.provider_billing_due_tasks_v1(invoice_id,milestone,scheduled_on)select i.id,x.milestone,x.due from public.provider_invoices i cross join lateral(values('J4',greatest(i.issued_on,i.due_on-3)),('J6',greatest(i.issued_on,i.due_on-1)),('J7',i.due_on),('OVERDUE',i.due_on+1))x(milestone,due)on conflict do nothing;
insert into public.notification_template_versions(template_code,version,event_type,category_code,locale,subject_template,body_template,cta_path_template,priority,mandatory,channels,variable_keys,status,effective_from,content_hash)
select code,1,event,'BILLING_CRITICAL',locale,subject,body,cta,'CRITICAL',true,array['IN_APP','EMAIL'],variables,'ACTIVE','2026-11-02',private.canonical_request_hash(jsonb_build_object('template',code,'version',1,'locale',locale,'subject',subject,'body',body,'cta',cta))from(values
('PROVIDER_PAYMENT_DUE','ProviderInvoiceReminderDueV1','fr-MA','Échéance de la facture {{number}}','Consultez le solde exigible dans votre dossier. Échéance : {{due_on}}. {{milestone}}.','/fr/sous-traitant/facturation/{{invoice_id}}?organizationId={{organization_id}}',array['number','balance','currency','due_on','milestone','invoice_id','organization_id']),
('PROVIDER_PAYMENT_DUE','ProviderInvoiceReminderDueV1','ar-MA','استحقاق الفاتورة {{number}}','راجعوا الرصيد المستحق في ملفكم. الأجل: {{due_on}}. {{milestone}}.','/ar/sous-traitant/facturation/{{invoice_id}}?organizationId={{organization_id}}',array['number','balance','currency','due_on','milestone','invoice_id','organization_id']),
('CLIENT_PROVIDER_RECEIPT','ProviderReceiptConfirmationDueV1','fr-MA','Un prestataire déclare un encaissement','Confirmez ou contestez le montant déclaré et son justificatif. Une confirmation ne réalise aucun paiement.','/fr/client/finances/encaissements-prestataire?organizationId={{organization_id}}',array['organization_id']),
('CLIENT_PROVIDER_RECEIPT','ProviderReceiptConfirmationDueV1','ar-MA','صرح مقدم خدمة بتحصيل','أكدوا المبلغ المصرح به ومستنده أو اعترضوا عليه. لا ينشئ التأكيد أي دفع.','/ar/client/finances/encaissements-prestataire?organizationId={{organization_id}}',array['organization_id'])
)x(code,event,locale,subject,body,cta,variables);
create function public.run_provider_billing_reminders_v1(p_limit integer default 100)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare today date:=(clock_timestamp()at time zone'Africa/Casablanca')::date;x record;counted integer:=0;corr uuid:=extensions.gen_random_uuid();begin
 if auth.role()is distinct from'service_role'then raise exception'PROVIDER_BILLING_REMINDER_DENIED'using errcode='42501';end if;
 if p_limit is null or p_limit not between 1 and 500 then raise exception'INVALID_REMINDER_LIMIT'using errcode='22023';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('provider-billing-reminders',0))then return jsonb_build_object('processed',0);end if;
 for x in select i.id,i.provider_organization_id,i.invoice_number,i.currency,i.due_on,b.outstanding_minor,t.milestone,m.user_id,case when u.raw_user_meta_data->>'locale'like'ar%'then'ar-MA'else'fr-MA'end locale from public.provider_billing_due_tasks_v1 t join public.provider_invoices i on i.id=t.invoice_id join public.provider_invoice_balances b on b.id=i.id join public.organization_memberships m on m.organization_id=i.provider_organization_id and m.status='ACTIVE'join auth.users u on u.id=m.user_id where t.scheduled_on<=today and b.outstanding_minor>0 and(t.milestone<>'OVERDUE'or private.provider_invoice_overdue_minor_v1(i.id)>0)and exists(select 1 from public.organization_member_roles mr where mr.membership_id=m.id and mr.role_code in('PROVIDER_OWNER','PROVIDER_ACCOUNTING')and mr.revoked_at is null)and not exists(select 1 from public.notification_instances n where n.recipient_user_id=m.user_id and n.deduplication_key='provider-invoice-reminder:'||i.id::text||':'||t.milestone)order by t.scheduled_on,i.id,t.milestone,m.user_id limit p_limit loop
  perform public.enqueue_notification(x.user_id,x.provider_organization_id,'PROVIDER_PAYMENT_DUE','ProviderInvoiceReminderDueV1',x.locale,jsonb_build_object('number',x.invoice_number,'balance',x.outstanding_minor::text,'currency',x.currency,'due_on',x.due_on::text,'milestone',case when x.locale='ar-MA'then case x.milestone when'OVERDUE'then'استحقاق متأخر؛ الفرص الجديدة مقيدة'else'تذكير بالاستحقاق'end else case x.milestone when'OVERDUE'then'Échéance dépassée ; nouvelles opportunités restreintes'else'Rappel avant échéance'end end,'invoice_id',x.id,'organization_id',x.provider_organization_id),'provider-invoice-reminder:'||x.id::text||':'||x.milestone,'provider_invoice',x.id::text,corr);counted:=counted+1;
 end loop;
 for x in select d.id,d.client_organization_id,m.user_id,case when u.raw_user_meta_data->>'locale'like'ar%'then'ar-MA'else'fr-MA'end locale from public.provider_financial_declarations_v1 d join public.organization_memberships m on m.organization_id=d.client_organization_id and m.status='ACTIVE'join auth.users u on u.id=m.user_id where d.kind='PAYABLE'and exists(select 1 from public.organization_member_roles mr where mr.membership_id=m.id and mr.role_code in('CLIENT_OWNER','CLIENT_ADMIN','CLIENT_ACCOUNTING')and mr.revoked_at is null)and not exists(select 1 from public.notification_instances n where n.recipient_user_id=m.user_id and n.deduplication_key='provider-receipt-confirm:'||d.id::text)order by d.declared_at,d.id,m.user_id limit p_limit loop
  perform public.enqueue_notification(x.user_id,x.client_organization_id,'CLIENT_PROVIDER_RECEIPT','ProviderReceiptConfirmationDueV1',x.locale,jsonb_build_object('organization_id',x.client_organization_id),'provider-receipt-confirm:'||x.id::text,'provider_financial_declaration',x.id::text,corr);counted:=counted+1;
 end loop;
 return jsonb_build_object('processed',counted);
end$$;
revoke all on function public.run_provider_billing_reminders_v1(integer)from public,anon,authenticated,service_role;
grant execute on function public.run_provider_billing_reminders_v1(integer)to service_role;
notify pgrst,'reload schema';

commit;
